param([Parameter(Mandatory)][string]$LegacyExecutable,[Parameter(Mandatory)][string]$Python,[string]$ProjectRoot=(Join-Path $PSScriptRoot '..'),[string]$BuildRoot='')
$ErrorActionPreference='Stop';$ProjectRoot=[IO.Path]::GetFullPath($ProjectRoot);if(!$BuildRoot){$BuildRoot=Join-Path $ProjectRoot 'out/build'};$BuildRoot=[IO.Path]::GetFullPath($BuildRoot);$LegacyExecutable=[IO.Path]::GetFullPath($LegacyExecutable)
$root=Join-Path $ProjectRoot ('artifacts/vault-upgrade-'+[Guid]::NewGuid().ToString('N'));New-Item -ItemType Directory -Force $root|Out-Null;Set-Content "$root/.synthetic-vault-test" 'Synthetic data only.'
$service=$null;$checks=0;$env:HIBERNATION_SESSION_KEY='vault-upgrade-fixture';$env:TEMP="$BuildRoot/tmp";$env:TMP=$env:TEMP
function Check($Value,$Name){if(!$Value){throw "CHECK FAILED: $Name"};$script:checks++;Write-Output "PASS $Name"}
function Wait-For([scriptblock]$Probe,$Name){$end=[DateTime]::UtcNow.AddSeconds(20);while([DateTime]::UtcNow-lt$end){if(& $Probe){return};Start-Sleep -Milliseconds 40};throw "TIMEOUT $Name"}
function Api($Path,$Data=$null){$a=@{Uri=$script:origin+$Path;Headers=@{Authorization='Bearer vault-upgrade-fixture'};TimeoutSec=12};if($null-ne$Data){$a.Method='Post';$a.ContentType='application/json';$a.Body=[Text.Encoding]::UTF8.GetBytes(($Data|ConvertTo-Json -Depth 35 -Compress))};Invoke-RestMethod @a}
function Start-App($Executable,$Name){Remove-Item "$root/ready.json" -ErrorAction SilentlyContinue;$script:service=Start-Process $Executable -ArgumentList ('--config "'+$root+'/config.json" --ready-file "'+$root+'/ready.json"') -WindowStyle Hidden -PassThru -RedirectStandardOutput "$root/$Name.log" -RedirectStandardError "$root/$Name-error.log";Wait-For {if($service.HasExited){throw "fixture startup failed ($Name)"};Test-Path "$root/ready.json"} 'ready';$script:origin='http://127.0.0.1:'+((Get-Content "$root/ready.json" -Raw|ConvertFrom-Json).port)}
function Stop-App{$null=Api '/api/shutdown' @{};Check ($service.WaitForExit(10000)-and$service.ExitCode-eq0) 'fixture exits cleanly'}
function Message($Text){$null=Api '/api/message' @{request_id=[Guid]::NewGuid().ToString('N');text=$Text};Wait-For {!(Api '/api/chat').busy} 'turn'}
function Probe($Mode){$result=& $Python "$ProjectRoot/tests/VaultProbe.py" $Mode $root "$BuildRoot/libsodium.dll";if($LASTEXITCODE-ne0){throw "independent vault probe failed: $Mode"};$result|ConvertFrom-Json}
try{
 $cfg=Get-Content "$ProjectRoot/config/example.json" -Raw|ConvertFrom-Json -AsHashtable;$cfg.Remove('frontend');$cfg.dataRoot="$root/data";$cfg.characterRoot="$ProjectRoot/character";$cfg.uiRoot="$ProjectRoot/ui";$cfg.pluginRoot="$BuildRoot/plugins";$cfg.plugins=@{};$cfg.profiles=@($cfg.profiles[0]);$cfg.solitudeIntervalMs=604800000;$cfg.idleBeforeSolitudeMs=86400000;$cfg|ConvertTo-Json -Depth 35|Set-Content "$root/config.json" -Encoding utf8
 Start-App $LegacyExecutable 'legacy';Message '升级以前，记住这一段经历。';$before=Api '/api/chat';Check ($before.messages.Count-eq2-and(Api '/api/memories').memories.Count-eq1) 'legacy binary creates a real encrypted conversation';Stop-App;$snapshot=Probe 'snapshot';Check ($snapshot.legacy_rows-gt10) 'all initial payloads use the actual legacy envelope'
 Start-App "$BuildRoot/hibernation-agent.exe" 'upgraded';$after=Api '/api/chat';Check (($after.messages|ConvertTo-Json -Depth 15 -Compress)-eq($before.messages|ConvertTo-Json -Depth 15 -Compress)) 'new binary restores the original conversation';Message '升级以后继续刚才的经历。';Check ((Api '/api/chat').messages.Count-eq4-and(Api '/api/memories').memories.Count-eq2) 'new-format writes continue without resetting memory';Stop-App
 $comparison=Probe 'compare';Check ($comparison.preserved_rows-eq$snapshot.legacy_rows) 'every original payload and provenance byte remains unchanged';$verified=Probe 'verify';Check ($verified.versions.HV1-gt0-and$verified.versions.HV2-gt0) 'independent library verifies mixed envelopes and metadata binding'
 Remove-Item "$root/ready.json" -ErrorAction SilentlyContinue;$service=Start-Process $LegacyExecutable -ArgumentList ('--config "'+$root+'/config.json" --ready-file "'+$root+'/ready.json"') -WindowStyle Hidden -PassThru -RedirectStandardOutput "$root/downgrade.log" -RedirectStandardError "$root/downgrade-error.log";Check ($service.WaitForExit(10000)-and$service.ExitCode-eq3-and!(Test-Path "$root/ready.json")) 'old binary rejects the upgraded codec before service startup';$null=Probe 'compare'
 Start-App "$BuildRoot/hibernation-agent.exe" 'reopened';Check ((Api '/api/chat').messages.Count-eq4-and(Api '/api/chat').health-eq'ok') 'failed downgrade leaves the new archive healthy';Stop-App
 @{completed=$true;checks=$checks;root=$root;legacyRows=$snapshot.legacy_rows;newRows=$verified.versions.HV2;timestamp=[DateTime]::UtcNow.ToString('O')}|ConvertTo-Json|Set-Content "$root/acceptance.json";Write-Output "Vault upgrade passed: $checks checks. Evidence: $root"
}finally{if($service){$service.Refresh();if(!$service.HasExited){try{$null=Api '/api/shutdown' @{};$service.WaitForExit(5000)|Out-Null}catch{};$service.Refresh();if(!$service.HasExited){Stop-Process -Id $service.Id}}}}
